import Foundation

nonisolated enum EmbeddedContentData {
    static func jsonData(for resourceName: String) -> Data? {
        let base64: String
        switch resourceName {
        case "questions_600":
            base64 = questions600Base64
        case "traffic_signs":
            base64 = trafficSignsBase64
        default:
            return nil
        }

        guard let compressed = Data(base64Encoded: base64, options: .ignoreUnknownCharacters) else {
            return nil
        }
        return try? (compressed as NSData).decompressed(using: .zlib) as Data
    }

